package com.example.helpdesk.web; import com.example.helpdesk.model.*; import com.example.helpdesk.repo.*; import com.example.helpdesk.service.*; import org.springframework.security.core.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*;
@Controller public class HomeController {private final TicketService service;private final AssetRepository assets;private final AssetService assetService;private final UserRepository users;public HomeController(TicketService s,AssetRepository a,AssetService as,UserRepository u){service=s;assets=a;assetService=as;users=u;}@GetMapping("/") String dashboard(Model m){m.addAttribute("open",service.count(TicketStatus.OPEN));m.addAttribute("progress",service.count(TicketStatus.IN_PROGRESS));m.addAttribute("resolved",service.count(TicketStatus.RESOLVED));m.addAttribute("assets",assets.count());return "dashboard";}@GetMapping("/tickets") String tickets(@RequestParam(required=false)String q,@RequestParam(required=false)Priority priority,Authentication a,Model m){User u=users.findByUsername(a.getName()).orElseThrow();m.addAttribute("tickets",service.visible(u,q,priority));m.addAttribute("q",q);m.addAttribute("selectedPriority",priority);m.addAttribute("priorities",Priority.values());return "tickets";}@GetMapping("/tickets/new") String newTicket(Model m){m.addAttribute("ticket",new Ticket());m.addAttribute("categories",Category.values());m.addAttribute("priorities",Priority.values());return "ticket-form";}@PostMapping("/tickets") String create(@ModelAttribute Ticket t,Authentication a){service.create(t,a.getName());return "redirect:/tickets";}@GetMapping("/tickets/{id}") String detail(@PathVariable Long id,Model m){m.addAttribute("ticket",service.get(id));m.addAttribute("history",service.history(id));m.addAttribute("statuses",TicketStatus.values());return "ticket-detail";}@GetMapping("/tickets/{id}/edit") String edit(@PathVariable Long id,Model m){m.addAttribute("ticket",service.get(id));m.addAttribute("categories",Category.values());m.addAttribute("priorities",Priority.values());return "ticket-edit";}@PostMapping("/tickets/{id}/edit") String saveEdit(@PathVariable Long id,@RequestParam String title,@RequestParam String description,@RequestParam Category category,@RequestParam Priority priority,Authentication a){service.updateFields(id,title,description,category,priority,a.getName());return "redirect:/tickets/"+id;}@PostMapping("/tickets/{id}/status") String status(@PathVariable Long id,@RequestParam TicketStatus status,@RequestParam(required=false)String notes,Authentication a){service.updateStatus(id,status,notes,a.getName());return "redirect:/tickets/"+id;}@GetMapping("/assets") String assetList(@RequestParam(required=false)String q,Model m){m.addAttribute("assets",assetService.all(q));m.addAttribute("q",q);return "assets";}@GetMapping("/assets/new") String assetNew(Model m){m.addAttribute("asset",new Asset());m.addAttribute("statuses",AssetStatus.values());return "asset-form";}@PostMapping("/assets") String assetCreate(@ModelAttribute Asset asset){assetService.save(asset);return "redirect:/assets";}}
